from format_lecon import Lesson,paras,table,steps
from diagnostics import comparison
from medicaments import window
l=Lesson('Épistaxis')
l.add('L’épistaxis est un saignement provenant des fosses nasales. Les {distinctions initiales} séparent une lésion locale, un terrain hémorragique et leurs associations. Le retentissement et la persistance déterminent l’urgence.',paras('Le sang peut sortir par une narine, par les deux ou couler dans le pharynx. La direction observée ne suffit pas à localiser avec certitude le vaisseau responsable ; une source antérieure peut aussi couler vers l’arrière.', 'Il faut distinguer une origine nasale d’un saignement buccal, d’une hémoptysie ou d’une hémorragie digestive. Du sang nasal avalé peut entraîner des nausées ou un vomissement sanglant ; le contexte et l’examen déterminent l’origine, sans conclusion sur la couleur seule.')+table(['Terme','Sens','Conséquence'],[['Antérieure.','Source proche de la partie antérieure du septum.','Souvent accessible à compression et geste local.'],['Postérieure ou non localisée.','Source difficile à identifier par simple inspection antérieure.','Évaluation ORL et niveau de surveillance adaptés.'],['Récidivante.','Épisodes répétés, même peu abondants.','Rechercher cause locale et terrain ; évaluer anémie selon contexte.'],['Essentielle.','Aucune autre cause retenue après évaluation adaptée.','Ce diagnostic ne dispense pas d’un nouveau bilan si le tableau change.']]),(1,4,5,6))
l.add('Les saignements antérieurs dominent les présentations usuelles. Les {limites épidémiologiques} empêchent de transformer des séries anciennes en classement suisse actuel des dix diagnostics. Une cause rare peut néanmoins imposer un geste urgent.',paras('L’atelier HUG de 2010 situe la majorité des sources dans la région antérieure ; les proportions diffèrent de celles de la recommandation française. Il n’est pas justifié d’en déduire une prévalence suisse contemporaine ni une probabilité individuelle.', 'Âge, traumatismes, sécheresse, inflammation et médicaments modifient le contexte. Les patients hospitalisés ne représentent pas les petits saignements arrêtés à domicile. Le tableau des diagnostics organise les mécanismes, sans prétendre les classer par fréquence mesurée.'),(1,4,5))
l.add('La muqueuse nasale est fine et richement vascularisée. Les {bases de l’hémostase nasale} expliquent les gestes locaux et les facteurs de persistance. Un défaut de coagulation peut amplifier une petite lésion.',paras('La région antéro-inférieure du septum comprend la tache vasculaire, ou région de Kiesselbach. Sa vascularisation reçoit des branches issues des réseaux carotidiens interne et externe ; les sources postérieures impliquent notamment le territoire sphénopalatin.', 'Compression et traitement ciblé agissent sur le point qui saigne. Les plaquettes, le facteur von Willebrand et la coagulation participent au caillot ; une anomalie de l’un de ces mécanismes ou un traitement antithrombotique peut prolonger l’hémorragie.', 'La fibrinolyse dégrade le caillot et constitue la cible d’un antifibrinolytique. Une pression artérielle élevée peut être associée au tableau, mais le stress et la douleur empêchent d’en faire automatiquement la cause unique.'),(1,3,4,5,6,13))
l.add('Les {urgences à exclure d’abord} sont respiratoires, circulatoires ou liées à une cause dangereuse. L’abondance visible ne mesure pas toujours la perte totale, car une partie du sang peut être avalée. Le bilan ne doit pas retarder les gestes vitaux.',table(['Priorité','🚩 Signal','Action'],[['E1 — Circulation.','Malaise, pâleur, tachycardie, hypotension ou saignement important persistant.','Appel 144 si détresse, surveillance et prise en charge de l’hémorragie.'],['E2 — Respiration.','Sang abondant dans le pharynx, altération de conscience ou difficulté respiratoire.','Équipe capable de protéger les voies aériennes.'],['E3 — Traumatisme.','Choc important, écoulement clair associé, signes visuels/neurologiques ou tuméfaction septale.','Bilan urgent ; éviter une instrumentation aveugle en cas de suspicion de lésion de la base du crâne.'],['E4 — Corps étranger dangereux.','Pile bouton ou produit caustique suspecté.','Extraction urgente par une équipe adaptée, sans attendre une aggravation.'],['E5 — Lésion structurale.','Récidive unilatérale avec obstruction, masse, signe orbitaire ou neurologique.','Endoscopie et imagerie ; pas de biopsie improvisée d’une masse vasculaire.'],['E6 — Terrain hémorragique.','Purpura, autres saignements, antithrombotique ou maladie connue.','Hémostase locale et évaluation systémique coordonnées.']]),(1,2,4,6,7,8,9,10,12,14))
l.add('L’anamnèse précise le côté initial, la durée, les récidives et les gestes déjà tentés. Les {questions orientées} recherchent une cause et un facteur aggravant. La liste exacte des médicaments et de leurs dernières prises est utile.',table(['Question','Orientation','Vigilance'],[['Grattage, mouchage, sécheresse ou spray nasal ?','Lésion muqueuse locale ou iatrogénie.','Ne pas attribuer une masse persistante à une simple irritation.'],['Choc, chirurgie ou geste nasal récent ?','Lésion traumatique ou postopératoire.','Rechercher complications septales, orbitaires ou crâniennes.'],['Enfant, objet introduit, écoulement fétide unilatéral ?','Corps étranger.','Identifier pile bouton ou matière caustique.'],['Anticoagulant, antiagrégant, erreur de dose ou changement récent ?','Risque hémorragique médicamenteux.','Évaluer aussi le risque thrombotique avant toute modification.'],['Gingivorragies, ecchymoses, règles abondantes, saignement après geste ?','Trouble de l’hémostase.','Histoire familiale et ancienneté orientent le bilan.'],['Obstruction chronique d’un côté ou télangiectasies familiales ?','Tumeur ou maladie vasculaire selon le tableau.','Un arrêt temporaire du saignement n’exclut pas la cause.']]),(3,4,5,6,7,8,11,12))
l.add('L’examen commence par les constantes, la conscience et les voies aériennes. Les {gestes ciblés} recherchent ensuite le siège et les signes associés. Le professionnel se protège des projections de sang.',table(['Geste','Recherche','Limite'],[['Évaluer pouls, pression et état général.','Retentissement circulatoire.','Une mesure isolée rassurante ne suffit pas si le saignement continue.'],['Observer nez, bouche et pharynx.','Côté initial, écoulement postérieur et autre origine possible.','La direction seule ne localise pas le vaisseau.'],['Rhinoscopie après préparation adaptée.','Point de saignement, lésion, croûtes, perforation ou corps étranger.','Ne pas multiplier les gestes aveugles dans un nez qui saigne.'],['Après traumatisme, inspecter le septum.','Hématome septal parfois bilatéral.','Une déformation externe faible n’exclut pas cette urgence.'],['Rechercher signes cutanéomuqueux.','Purpura, ecchymoses ou télangiectasies.','Compléter par le contexte et les examens adaptés.'],['Évaluer yeux, face et neurologie selon les symptômes.','Lésion traumatique ou extension d’une masse.','Un déficit nouveau demande une évaluation rapide.']]),(1,2,4,5,6,12))
l.add('L’{approche syndromique} regroupe les indices avant de nommer la maladie. Une lésion locale et un terrain hémorragique peuvent coexister. La persistance malgré un traitement correct impose de réexaminer le mécanisme.',table(['Syndrome','Signes fonctionnels','Constats possibles'],[['7.1 — Antérieur localisé.','Sang extériorisé après irritation ou spontané.','Point septal accessible.'],['7.2 — Profond ou non localisé.','Écoulement pharyngé, persistance malgré gestes simples.','Source non visible en avant.'],['7.3 — Traumatique.','Douleur, obstruction, choc récent.','Déformation, plaie ou hématome septal.'],['7.4 — Unilatéral obstructif.','Nez bouché, écoulement fétide ou récidives.','Corps étranger ou masse à rechercher.'],['7.5 — Cutanéomuqueux.','Épistaxis avec autres saignements.','Purpura ou anomalies biologiques orientées.'],['7.6 — Vasculaire familial.','Épisodes répétés dans un contexte personnel et familial.','Télangiectasies et possible atteinte viscérale.']]),(1,2,3,4,5,6,7,12))
l.add('Le diagnostic positif confirme l’origine nasale et caractérise la gravité. Les {diagnostics à confronter} ne sont pas tous exclus par la visibilité d’un petit vaisseau antérieur. Leurs indices doivent être interprétés ensemble.',paras('Une épistaxis essentielle se retient après une évaluation compatible et l’absence de cause pertinente identifiée. La récidive, l’unilatéralité persistante ou un nouveau symptôme peut nécessiter une endoscopie même si une ectasie antérieure est visible.', 'Le diagnostic de thrombopénie repose sur la numération, mais sa nature immune demande d’exclure d’autres causes. La maladie de von Willebrand requiert des analyses spécialisées ; un simple bilan standard ne décrit pas tous ses types.')+comparison(),(1,3,4,5,6,7,9,10,11,12))
l.add('Les examens répondent à la gravité et à l’hypothèse clinique. Les {quatre niveaux du bilan} évitent un bilan identique pour toute petite épistaxis. Le contrôle d’une hémorragie menaçante se poursuit pendant les investigations.',paras('9.a — Référence : examen nasal, éventuellement endoscopique, pour localiser ; bilan ciblé pour établir la cause systémique ou structurale.', '9.b — Un épisode simple arrêté sans autre indice ne nécessite pas automatiquement tous les tests. Si saignement sévère : hémogramme, hémostase, fonction rénale et bilan prétransfusionnel selon l’équipe et le retentissement.', '9.c — Sous AVK, contrôler l’INR. Pour un anticoagulant direct, un INR normal n’évalue pas correctement son activité ; l’heure de prise, la fonction rénale et les tests appropriés sont discutés avec le laboratoire et l’équipe.', '9.d — Endoscopie si source non localisée, persistance, récidives ou suspicion de lésion ; imagerie si traumatisme complexe ou masse. Le prélèvement tumoral est planifié après appréciation de la vascularisation ; la suspicion d’angiofibrome contre-indique une biopsie improvisée.'),(2,3,4,5,6,9,10,11,15,17))
l.add('L’{arbre décisionnel} conserve la priorité aux fonctions vitales. Les gestes locaux sont réévalués selon leur effet et le terrain. Une récidive ne se traite pas indéfiniment sans chercher sa cause.',steps('Détresse respiratoire ou circulatoire → prise en charge urgente et contrôle de l’hémorragie en parallèle.', 'Patient stable sans traumatisme complexe ni corps étranger dangereux → assis, tête légèrement en avant, compression de la partie souple du nez dix à quinze minutes sans relâcher.', 'Si persistance → examen préparé et avis adapté ; traiter un point identifié ou recourir au tamponnement selon indication.', 'Si source postérieure, non localisée, saignement réfractaire ou terrain fragile → filière ORL hospitalière, surveillance et discussion d’hémostase spécialisée.', 'Si récidive unilatérale, obstruction, purpura ou contexte familial → investigation étiologique après stabilisation.', 'Avant retour → confirmer contrôle, consignes, suivi et rendez-vous de retrait si matériel non résorbable.'),(1,2,4,5,7,8,14))
drug=window(l)
l.add('La prise en charge associe hémostase locale, correction du retentissement et traitement de la cause. Les {modalités suisses et leurs limites} dépendent du produit, du terrain et de l’expertise disponible. L’anticoagulant n’est pas interrompu automatiquement pour un saignement contrôlé.',paras('11.A — Arrêter le saignement, protéger respiration et circulation, prévenir récidive et complications des gestes.', '11.B — Si le patient est stable, comprimer les deux ailes souples contre le septum, en respirant par la bouche, pendant dix à quinze minutes sans vérification répétée. Un mouchage doux unique peut enlever les caillots avant compression dans un contexte simple ; pas de manœuvre forcée devant traumatisme complexe ou corps étranger. Les sources proposent des durées voisines, parfois quinze à vingt minutes, sans en faire un motif d’attendre devant une alarme.', 'Une cautérisation traite un point correctement identifié ; éviter la cautérisation septale bilatérale simultanée. Tamponnement, endoscopie, coagulation artérielle ou embolisation sont choisis selon siège, gravité et échec des étapes précédentes. Le matériel, la pression, la préparation et la surveillance relèvent de l’équipe formée.', 'Une épistaxis prolongée ou récidivante peut relever d’acide tranexamique oral dans une situation sélectionnée ; la fenêtre précise l’indication et la dose AIPS de Cyklokapron. Les anciens schémas HUG d’onguent, antibiotique ou anesthésique ne sont pas repris comme prescriptions actuelles sans vérification du produit. La prévention infectieuse d’un tamponnement dépend du dispositif, de la durée et du terrain, selon protocole local.', 'Le prescripteur et l’équipe d’hémostase décident d’une éventuelle modification ou neutralisation d’un antithrombotique si hémorragie grave, persistante ou surdosage. Le risque thrombotique compte aussi ; l’arrêt seul d’un antiagrégant ne corrige pas immédiatement son effet. Les vieux documents ne décrivent pas toute la disponibilité actuelle des antidotes. L’EHRA conseille au patient de ne pas sauter seul une dose devant un petit saignement ; une adaptation temporaire relève d’une décision clinique individualisée.', '11.C — Contrôler récidive, retentissement, tolérance du tamponnement et résultats du bilan. Une perte postérieure persistante peut être discrète de face. Après traumatisme, la recherche d’un hématome septal reste distincte de l’arrêt du sang.', '11.D — Retour seulement si situation stable et plan fiable. Enseigner compression, signes d’appel urgent et recours en cas de récidive ; préciser retrait du matériel, contrôle ORL et suivi du traitement causal. Un tamponnement postérieur ou une hémorragie grave requiert une surveillance adaptée.')+paras(drug),(1,2,4,5,13,14,15,16,17))
l.add('La prévention vise les irritations et les causes identifiées. Les {actions aux trois niveaux} sont adaptées au terrain. Des récidives ne doivent pas être masquées par des traitements locaux répétés sans examen.',paras('Primaire : éviter grattage et traumatisme, corriger une sécheresse selon conseil professionnel, revoir la technique des sprays et garder les piles et petits objets hors de portée des enfants.', 'Secondaire : savoir comprimer, reconnaître l’hémorragie grave et faire évaluer un saignement récidivant ou unilatéral. Rechercher un trouble hémorragique si histoire personnelle ou familiale évocatrice.', 'Tertiaire : suivre anémie et cause de fond, organiser retrait et contrôle après geste, adapter les traitements avec leurs prescripteurs. Un patient atteint d’une maladie hémorragique doit disposer d’un plan personnalisé pour les épisodes et les interventions.'),(3,4,5,7,8,11,14))
l.add('Comprimer la partie souple du nez, tête légèrement en avant. Une hémorragie persistante, une détresse ou une pile bouton impose une action urgente. Une récidive unilatérale avec obstruction demande un bilan. L’arrêt du sang ne remplace pas l’identification de la cause.',refs=(1,4,5,7,8,14))
l.quiz([
('Tout sang visible dans la gorge prouve-t-il une source postérieure ?','Non : une source antérieure peut aussi couler vers l’arrière.'),
('Où appliquer la compression ?','Sur les ailes souples du nez contre le septum, pas seulement sur le relief osseux.'),
('Faut-il relâcher toutes les minutes pour vérifier ?','Non : la compression doit être continue pendant la durée indiquée.'),
('La tête doit-elle être basculée en arrière ?','Non : le patient stable se penche légèrement en avant pour limiter l’écoulement dans le pharynx.'),
('Un volume visible faible exclut-il une perte importante ?','Non : une partie du sang peut être avalée ou couler en arrière.'),
('Une pile bouton nasale peut-elle attendre un contrôle différé ?','Non : elle exige une extraction urgente à cause du risque de brûlure.'),
('Une ectasie antérieure visible clôt-elle tout bilan de récidive ?','Non : une autre cause associée peut nécessiter une endoscopie.'),
('Peut-on cautériser largement les deux faces septales en même temps ?','Non : cette pratique augmente le risque de lésion et de perforation.'),
('L’INR mesure-t-il correctement l’activité de tous les anticoagulants ?','Non : il est utilisé pour les AVK, pas comme mesure universelle des anticoagulants directs.'),
('Faut-il arrêter seul tout anticoagulant devant un petit saignement contrôlé ?','Non : le bénéfice thrombotique et le contexte hémorragique doivent être évalués.'),
('Une thrombopénie prouve-t-elle sa cause immune ?','Non : les autres causes doivent être recherchées selon le tableau.'),
('Une masse vasculaire suspecte peut-elle être biopsiée à l’aveugle ?','Non : une suspicion d’angiofibrome impose une stratégie d’imagerie et de traitement spécialisée.'),
('La dose orale de Cyklokapron peut-elle être appliquée par voie nasale ?','Non : voie et indication ne se transposent pas automatiquement.'),
('Le contrôle après méchage est-il facultatif ?','Non : retrait éventuel, tolérance, récidive et cause doivent être organisés.')],(1,3,4,5,7,8,10,12,13,14))
l.write()
